Commit:     Geoff Lankow <geoff@darktrojan.net>
CommitDate: Thu Jul 31 22:34:47 2025 +1200

    Bug 1980371 - Enable about:certerror in Thunderbird. r=aleca
    All the pieces exist, we just need to connect them together.

    This is far from perfect, the "Go Back" button won't do much that's useful in a lot of cases,
    and the "Learn More" link points to a SUMO page that isn't there, but at least the user is
    informed of the problem.

    Differential Revision: https://phabricator.services.mozilla.com/D260070

diff --git a/mail/app/profile/all-thunderbird.js b/mail/app/profile/all-thunderbird.js
index 59b451c6f47..07bc4cc73a5 100644
--- a/mail/app/profile/all-thunderbird.js
+++ b/mail/app/profile/all-thunderbird.js
@@ -279,6 +279,12 @@ pref("security.osclientcerts.autoload", false);
   pref("security.sandbox.content.syscall_whitelist", "");
 #endif

+// about:neterror
+pref("security.certerrors.permanentOverride", true);
+pref("security.certerrors.mitm.priming.enabled", false);
+pref("security.certerrors.mitm.auto_enable_enterprise_roots", true);
+pref("security.certerrors.felt-privacy-v1", false);
+
 // Symmetric (can be overridden by individual extensions) update preferences.
 // e.g.
 //  extensions.{GUID}.update.enabled
diff --git a/mail/components/AboutRedirector.sys.mjs b/mail/components/AboutRedirector.sys.mjs
index 714af3e9174..da9566cb1ec 100644
--- a/mail/components/AboutRedirector.sys.mjs
+++ b/mail/components/AboutRedirector.sys.mjs
@@ -9,8 +9,16 @@ AboutRedirector.prototype = {

   // Each entry in the map has the key as the part after the "about:" and the
   // value as a record with url and flags entries. Note that each addition here
-  // should be coupled with a corresponding addition in mailComponents.manifest.
+  // should be coupled with a corresponding addition in components.conf.
   _redirMap: {
+    certerror: {
+      url: "chrome://global/content/aboutNetError.html",
+      flags:
+        Ci.nsIAboutModule.URI_SAFE_FOR_UNTRUSTED_CONTENT |
+        Ci.nsIAboutModule.URI_CAN_LOAD_IN_CHILD |
+        Ci.nsIAboutModule.ALLOW_SCRIPT |
+        Ci.nsIAboutModule.HIDE_FROM_ABOUTABOUT,
+    },
     newserror: {
       url: "chrome://messenger/content/newsError.xhtml",
       flags: Ci.nsIAboutModule.ALLOW_SCRIPT,
